import { describe, expect, it, vi } from 'vitest';
import { BUILD_ID_RE, assertBuildId, buildMeta, formatBuildId, parseBuildId, parseBuildMeta, parseVaultBanner, vaultBanner } from './build-id.ts';
import { type Git, localBuild, resolveDeployConfig, stampedDeploy, stampedDeployArgv, wranglerEnv } from './local-build.ts';

const SHA = '0485faa1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7';

describe('build id format', () => {
  it('is the first 12 hex characters of the commit, with -dirty for a tree with changes', () => {
    expect(formatBuildId(SHA, false)).toBe('0485faa1c2d3');
    expect(formatBuildId(SHA, true)).toBe('0485faa1c2d3-dirty');
    expect(formatBuildId('0485faa1c2d3', false)).toBe('0485faa1c2d3');
    for (const bad of ['', '0485faa', SHA.toUpperCase(), `${SHA} `, 'g485faa1c2d3']) expect(() => formatBuildId(bad, false), bad).toThrow();
  });

  it('parses only well-formed ids', () => {
    expect(parseBuildId('0485faa1c2d3')).toEqual({ id: '0485faa1c2d3', commit: '0485faa1c2d3', dirty: false });
    expect(parseBuildId('0485faa1c2d3-dirty')).toEqual({ id: '0485faa1c2d3-dirty', commit: '0485faa1c2d3', dirty: true });
    for (const bad of [undefined, null, 1, '', 'unknown', '0485faa1c2d', '0485faa1c2d3e', '0485faa1c2d3-DIRTY', '0485faa1c2d3-dirty ', SHA]) {
      expect(parseBuildId(bad), String(bad)).toBeNull();
    }
  });

  it('never lets anything but an id into a JS comment or an HTML attribute', () => {
    for (const bad of ['0485faa1c2d3 */ alert(1) /*', '0485faa1c2d3"><script>', '']) {
      expect(() => assertBuildId(bad)).toThrow();
      expect(() => vaultBanner(bad)).toThrow();
      expect(() => buildMeta(bad)).toThrow();
    }
    expect(BUILD_ID_RE.test(assertBuildId('0485faa1c2d3-dirty'))).toBe(true);
  });
});

describe('bundle stamps', () => {
  it('the vault banner round-trips, at the start of the bundle only', () => {
    const js = `${vaultBanner('0485faa1c2d3')}\nvar a=1;`;
    expect(parseVaultBanner(js)?.id).toBe('0485faa1c2d3');
    expect(parseVaultBanner(`var a=1;\n${vaultBanner('0485faa1c2d3')}`)).toBeNull();
    expect(parseVaultBanner('var a=1;')).toBeNull();
    expect(parseVaultBanner('/* hana-build nope */')).toBeNull();
  });

  it('the auth meta round-trips; a page with none, two or a malformed one has no id', () => {
    const meta = buildMeta('0485faa1c2d3-dirty');
    expect(meta).toBe('<meta name="hana-build" content="0485faa1c2d3-dirty">');
    expect(parseBuildMeta(`<head>${meta}</head>`)).toEqual({ id: '0485faa1c2d3-dirty', commit: '0485faa1c2d3', dirty: true });
    expect(parseBuildMeta('<head></head>')).toBeNull();
    expect(parseBuildMeta(`${meta}${buildMeta('111111111111')}`)).toBeNull();
    expect(parseBuildMeta('<meta name="hana-build" content="x">')).toBeNull();
  });
});

describe('localBuild', () => {
  const git = (head: string, status: string): Git => (args) => (args[0] === 'rev-parse' ? `${head}\n` : status);

  it('stamps HEAD, -dirty when git status lists anything (untracked files too)', () => {
    expect(localBuild(git(SHA, ''))).toEqual({ id: '0485faa1c2d3', commit: '0485faa1c2d3', dirty: false, head: SHA });
    expect(localBuild(git(SHA, ' M apps/api/src/index.ts\n')).id).toBe('0485faa1c2d3-dirty');
    expect(localBuild(git(SHA, '?? apps/api/src/new.ts\n')).dirty).toBe(true);
  });

  it('asks git for untracked files and HEAD itself', () => {
    const calls: string[][] = [];
    localBuild((args) => {
      calls.push([...args]);
      return args[0] === 'rev-parse' ? SHA : '';
    });
    expect(calls).toEqual([
      ['rev-parse', '--verify', 'HEAD'],
      ['status', '--porcelain=v1', '--untracked-files=normal'],
    ]);
  });

  it('fails outside a git checkout or on a strange answer, never returning a made-up id', () => {
    expect(() =>
      localBuild(() => {
        throw new Error('not a git repository');
      }),
    ).toThrow(/git checkout/u);
    expect(() => localBuild(git('HEAD', ''))).toThrow(/commit hash/u);
  });

  it('reads this checkout', () => {
    const b = localBuild();
    expect(b.head).toMatch(/^[0-9a-f]{40}$/u);
    expect(b.id.startsWith(b.head.slice(0, 12))).toBe(true);
  });
});

describe('stampedDeploy', () => {
  const build = () => ({ id: '0485faa1c2d3', commit: '0485faa1c2d3', dirty: false, head: SHA });
  /** A generated config (its `//` header, then JSON) for this env. */
  const config = (envName: string | null, extra: Record<string, unknown> = {}) =>
    `// Generated by apps/api/scripts/gen-wrangler.ts from envs/x.json: edit the manifest, not this file.\n${JSON.stringify({ name: 'hana-api', vars: envName === null ? {} : { ENV_NAME: envName }, d1_databases: [{ binding: 'DB', database_name: 'hana-x' }], ...extra }, null, 2)}\n`;
  /** Only `files` exist (absolute paths), each with the config for `envName`. */
  const fsOf = (files: Record<string, string | null>) => ({
    exists: (p: string) => Object.hasOwn(files, p),
    readConfig: (p: string) => {
      const v = files[p];
      if (v === undefined || v === null) throw new Error('ENOENT');
      return v;
    },
  });
  /** The names in a directory, from `files`' paths. */
  const listOf = (files: Record<string, string | null>) => (dir: string) => Object.keys(files).filter((p) => p.startsWith(`${dir}/`) && !p.slice(dir.length + 1).includes('/')).map((p) => p.slice(dir.length + 1));
  const deps = (files: Record<string, string | null>, more: Record<string, unknown> = {}) => {
    const wrangler = vi.fn((_argv: string[], _env: NodeJS.ProcessEnv) => 0);
    const lines: string[] = [];
    return { wrangler, lines, d: { build, wrangler, log: (l: string) => lines.push(l), cwd: '/w', env: { PATH: '/bin' }, listDir: listOf(files), ...fsOf(files), ...more } };
  };

  it('deploys exactly one resolved config, by its absolute path, stamped', () => {
    const { wrangler, lines, d } = deps({ '/w/wrangler.jsonc': config('sandbox-dev') });
    expect(stampedDeploy([], d)).toBe(0);
    expect(wrangler).toHaveBeenCalledWith(['deploy', '-c', '/w/wrangler.jsonc', '--var', 'HANA_BUILD:0485faa1c2d3'], { PATH: '/bin' });
    expect(lines.join('\n')).toContain('0485faa1c2d3');
    // -c (relative or absolute, once) and --dry-run.
    const a = deps({ '/w/wrangler.vault.jsonc': config(null), '/abs/x.jsonc': config('sandbox-dev') });
    expect(stampedDeploy(['-c', 'wrangler.vault.jsonc'], a.d)).toBe(0);
    expect(stampedDeploy(['--config=/abs/x.jsonc', '--dry-run'], a.d)).toBe(0);
    expect(a.wrangler.mock.calls.map((c) => c[0])).toEqual([
      ['deploy', '-c', '/w/wrangler.vault.jsonc', '--var', 'HANA_BUILD:0485faa1c2d3'],
      ['deploy', '-c', '/abs/x.jsonc', '--dry-run', '--var', 'HANA_BUILD:0485faa1c2d3'],
    ]);
    expect(stampedDeployArgv('0485faa1c2d3', '/w/wrangler.jsonc')).toEqual(['deploy', '-c', '/w/wrangler.jsonc', '--var', 'HANA_BUILD:0485faa1c2d3']);
    expect(() => stampedDeployArgv('nope', '/w/x.jsonc')).toThrow();
    expect(() => stampedDeployArgv('0485faa1c2d3', 'x.jsonc')).toThrow(/absolute/u);
  });

  it('passes wrangler’s failure on, and says when the tree is dirty', () => {
    const lines: string[] = [];
    const dirty = () => ({ id: '0485faa1c2d3-dirty', commit: '0485faa1c2d3', dirty: true, head: SHA });
    expect(stampedDeploy([], { build: dirty, wrangler: () => 3, log: (l) => lines.push(l), cwd: '/w', env: {}, listDir: () => [], ...fsOf({ '/w/wrangler.jsonc': config('sandbox-dev') }) })).toBe(3);
    expect(lines.join('\n')).toMatch(/uncommitted changes/u);
  });

  it('refuses a HANA_BUILD from the command line (only git sets it)', () => {
    const { wrangler, d } = deps({ '/w/wrangler.jsonc': config('sandbox-dev') });
    expect(() => stampedDeploy(['--var', 'HANA_BUILD:aaaaaaaaaaaa'], d)).toThrow(/HANA_BUILD/u);
    expect(wrangler).not.toHaveBeenCalled();
  });

  it('D931, the local* guard: refuses a config for a local* env, one it can’t read or find, a TOML one', () => {
    for (const name of ['local', 'local-dev', 'local-e2e', 'localx']) {
      const { wrangler, lines, d } = deps({ '/w/wrangler.jsonc': config(name) });
      expect(stampedDeploy([], d), name).toBe(1);
      expect(lines.join('\n')).toMatch(/local\* envs run on wrangler dev, never deployed/u);
      expect(wrangler).not.toHaveBeenCalled();
    }
    for (const files of [{}, { '/w/wrangler.jsonc': null }, { '/w/wrangler.jsonc': '{not json' }, { '/w/wrangler.toml': 'name = "x"' }]) {
      const { wrangler, d } = deps(files as Record<string, string | null>);
      expect(stampedDeploy([], d), JSON.stringify(files)).toBe(1);
      expect(wrangler).not.toHaveBeenCalled();
    }
    const { d } = deps({ '/w/wrangler.jsonc': config('sandbox-dev') });
    expect(stampedDeploy(['-c', 'wrangler.toml'], d)).toBe(1);
    // A Worker whose config names no env (console-auth, files) is not refused; prod-local is not a local* name.
    expect(stampedDeploy([], deps({ '/w/wrangler.jsonc': config(null) }).d)).toBe(0);
    expect(stampedDeploy([], deps({ '/w/wrangler.jsonc': config('prod-local') }).d)).toBe(0);
  });

  it('after PR 159’s second review: only -c (once), --require-migrations and --dry-run; nothing that changes the config or its vars', () => {
    for (const argv of [
      ['--var', 'ENV_NAME:local-dev'],
      ['--var=X:1'],
      ['--define', 'NETWORK:"testnet"'],
      ['--env', 'x'],
      ['-e', 'x'],
      ['--cwd', '/other'],
      ['--cwd=/other'],
      ['--secrets-file', 'secrets.json'],
      ['--secrets-file=secrets.json'],
      ['-c', 'a.jsonc', '-c', 'b.jsonc'],
      ['--config', 'a.jsonc', '--config=b.jsonc'],
      ['--script', 'src/index.ts'],
      ['src/index.ts'],
      ['-c'],
      ['-c', '--dry-run'],
      ['--require-migrations', 'db:0034_x.sql'],
      ['--require-migrations', 'DB:0034_x.sql', '--require-migrations', 'DB:0034_x.sql'],
    ]) {
      const { wrangler, lines, d } = deps({ '/w/wrangler.jsonc': config('sandbox-dev'), '/w/a.jsonc': config('sandbox-dev'), '/w/b.jsonc': config('sandbox-dev') });
      expect(stampedDeploy(argv, d), argv.join(' ')).toBe(1);
      expect(lines.join('\n'), argv.join(' ')).toMatch(/^Deploy refused: /mu);
      expect(wrangler, argv.join(' ')).not.toHaveBeenCalled();
    }
  });

  it('after PR 159’s second review: wrangler’s own discovery order (wrangler.json, then .jsonc, then .toml) in the directory, and never a redirect', () => {
    const both = deps({ '/w/wrangler.json': config('sandbox-dev'), '/w/wrangler.jsonc': config('local-dev') });
    expect(stampedDeploy([], both.d)).toBe(0);
    expect(both.wrangler.mock.calls[0]![0]).toEqual(['deploy', '-c', '/w/wrangler.json', '--var', 'HANA_BUILD:0485faa1c2d3']);
    expect(resolveDeployConfig(undefined, '/w', (p) => p === '/w/wrangler.jsonc' || p === '/w/wrangler.toml')).toBe('/w/wrangler.jsonc');
    expect(resolveDeployConfig(undefined, '/w', (p) => p === '/w/wrangler.toml')).toBe('/w/wrangler.toml');
    // A `.wrangler/deploy/config.json` redirect, or a config in a parent directory, is never what's deployed: wrangler
    // gets -c with the file checked (and with -c it follows no redirect).
    expect(resolveDeployConfig(undefined, '/w', (p) => p === '/w/.wrangler/deploy/config.json' || p === '/wrangler.jsonc')).toBeNull();
    const redirect = deps({ '/w/.wrangler/deploy/config.json': '{"configPath":"../../local.jsonc"}', '/w/wrangler.jsonc': config('sandbox-dev') });
    expect(stampedDeploy([], redirect.d)).toBe(0);
    expect(redirect.wrangler.mock.calls[0]![0]!.slice(0, 3)).toEqual(['deploy', '-c', '/w/wrangler.jsonc']);
  });

  it('after PR 159’s third review: CLOUDFLARE_ENV and WRANGLER_CI_OVERRIDE_NAME refused, in the environment or a .env file wrangler would load; wrangler runs without them', () => {
    for (const env of [{ CLOUDFLARE_ENV: 'x' }, { WRANGLER_CI_OVERRIDE_NAME: 'other-worker' }, { CLOUDFLARE_ENV: '' }]) {
      const { wrangler, lines, d } = deps({ '/w/wrangler.jsonc': config('sandbox-dev') }, { env });
      expect(stampedDeploy([], d), JSON.stringify(env)).toBe(1);
      expect(lines.join('\n')).toMatch(/is set: it changes what wrangler deploys/u);
      expect(wrangler).not.toHaveBeenCalled();
    }
    for (const [file, text] of [
      ['/w/.env', 'CLOUDFLARE_API_TOKEN=t\nCLOUDFLARE_ENV=x\n'],
      ['/w/.env.local', 'export WRANGLER_CI_OVERRIDE_NAME = other'],
      ['/w/.env.x', '  CLOUDFLARE_ENV="x"'],
      ['/c/.env', 'CLOUDFLARE_ENV=x'],
    ] as const) {
      const { wrangler, lines, d } = deps({ '/c/wrangler.jsonc': config('sandbox-dev'), [file]: text });
      expect(stampedDeploy(['-c', '/c/wrangler.jsonc'], d), file).toBe(1);
      expect(lines.join('\n'), file).toContain(`${file} sets`);
      expect(wrangler).not.toHaveBeenCalled();
    }
    // A .env with other variables is fine; wrangler gets the environment without the refused names.
    const ok = deps({ '/w/wrangler.jsonc': config('sandbox-dev'), '/w/.env': 'CLOUDFLARE_ACCOUNT_ID=abc\n# CLOUDFLARE_ENV=x is a comment\n' });
    expect(stampedDeploy([], ok.d)).toBe(0);
    expect(ok.wrangler.mock.calls[0]![1]).toEqual({ PATH: '/bin' });
    expect(wranglerEnv({ PATH: '/bin', CLOUDFLARE_ENV: 'x', WRANGLER_CI_OVERRIDE_NAME: 'y', CLOUDFLARE_API_TOKEN: 't' })).toEqual({ PATH: '/bin', CLOUDFLARE_API_TOKEN: 't' });
  });

  it('after PR 159’s third review: a config with an env section, or a __proto__/constructor/prototype key at any depth, is refused', () => {
    const withEnv = JSON.stringify({ name: 'hana-api', vars: { ENV_NAME: 'sandbox-dev' }, env: { x: { vars: { ENV_NAME: 'local-x' } } } });
    const proto = '{"name":"hana-api","vars":{"ENV_NAME":"sandbox-dev"},"__proto__":{"vars":{"ENV_NAME":"local-x"}}}';
    const nested = '{"name":"hana-api","vars":{"ENV_NAME":"sandbox-dev","constructor":{"prototype":{}}}}';
    for (const [text, words] of [
      [withEnv, /has an "env" section/u],
      [proto, /has a "__proto__" key/u],
      [nested, /has a "(?:constructor|prototype)" key/u],
    ] as const) {
      const { wrangler, lines, d } = deps({ '/w/wrangler.jsonc': text });
      expect(stampedDeploy([], d), text).toBe(1);
      expect(lines.join('\n')).toMatch(words);
      expect(wrangler).not.toHaveBeenCalled();
    }
  });

  it('after PR 159’s second review: the migration check runs on the same config that is deployed (pnpm passes extra args to the wrapper)', () => {
    const checked: string[] = [];
    const requireMigrations = vi.fn((i: { configPath: string; binding: string; required: string }) => (checked.push(`${i.configPath} ${i.binding} ${i.required}`), null));
    const ok = deps({ '/w/wrangler.jsonc': config('sandbox-dev'), '/w/other.jsonc': config('sandbox-dev') }, { requireMigrations });
    // `pnpm run deploy -c other.jsonc` runs the wrapper with both: the check and the deploy name other.jsonc.
    expect(stampedDeploy(['--require-migrations', 'DB:0034_origin_confirmations.sql', '-c', 'other.jsonc'], ok.d)).toBe(0);
    expect(checked).toEqual(['/w/other.jsonc DB 0034_origin_confirmations.sql']);
    expect(ok.wrangler.mock.calls[0]![0]!.slice(0, 3)).toEqual(['deploy', '-c', '/w/other.jsonc']);
    // A refused check deploys nothing.
    const no = deps({ '/w/wrangler.jsonc': config('sandbox-dev') }, { requireMigrations: () => 'refused: hana-x lacks 0034_origin_confirmations.sql' });
    expect(stampedDeploy(['--require-migrations', 'DB:0034_origin_confirmations.sql'], no.d)).toBe(1);
    expect(no.wrangler).not.toHaveBeenCalled();
    expect(no.lines.join('\n')).toMatch(/lacks 0034/u);
  });
});
